def amicable_numbers_sum(n):
    """
    Sum all amicable numbers from 1 to n.

    Amicable numbers are pairs of numbers where each number is the sum of 
    the proper divisors of the other number. For example, 220 and 284 are 
    amicable because the sum of divisors of 220 (excluding 220) is 284, 
    and the sum of divisors of 284 (excluding 284) is 220.
    """
    def sum_of_proper_divisors(num):
        """Return the sum of proper divisors of num (divisors excluding num itself)"""
        if num <= 1:
            return 0
        divisor_sum = 1  # 1 is always a proper divisor for num > 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                divisor_sum += i
                if i != num // i:  # avoid counting the square root twice
                    divisor_sum += num // i
        return divisor_sum

    amicable_set = set()

    for i in range(1, n + 1):
        sum_of_divisors_i = sum_of_proper_divisors(i)
        # Check if i and sum_of_divisors_i form an amicable pair
        if sum_of_divisors_i <= n and sum_of_divisors_i != i:
            sum_of_divisors_j = sum_of_proper_divisors(sum_of_divisors_i)
            if sum_of_divisors_j == i:
                amicable_set.add(i)

    return sum(amicable_set)
