def is_Sub_Array(arr1, arr2):
    """
    Check whether arr2 is a sublist of arr1 or not.
    A sublist means arr2 elements appear in arr1 in the same order (not necessarily consecutive).
    """
    if len(arr2) == 0:
        return True

    if len(arr2) > len(arr1):
        return False

    # Use two pointers approach
    i = 0  # pointer for arr1
    j = 0  # pointer for arr2

    while i < len(arr1) and j < len(arr2):
        if arr1[i] == arr2[j]:
            j += 1
        i += 1

    return j == len(arr2)
