def get_max_sum(n):
    """
    Find the maximum sum possible by using the equation:
    f(n) = max((f(n/2) + f(n/3) + f(n/4) + f(n/5)), n)
    """
    memo = {}

    def f(x):
        if x in memo:
            return memo[x]

        if x == 0:
            return 0

        # Calculate sum of recursive calls with integer division
        recursive_sum = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)

        # Return maximum of recursive sum or n itself
        result = max(recursive_sum, x)
        memo[x] = result
        return result

    return f(n)
```

